    let _layoutCache = { valid: false, topHud: 98, bottomHud: 130, rowWidth: 0, rowHeight: 0, stageW: 0, stageH: 0, parentW: 0, parentH: 0, stageOffX: 0, stageOffY: 0 };
    function invalidateLayoutCache() { _layoutCache.valid = false; }
