      const rb = (typeof ThreeVFXEffects !== 'undefined' && ThreeVFXEffects.startRain3D) ? ThreeVFXEffects
               : (window.ThreeVFX && window.ThreeVFX.isActive()) ? window.ThreeVFX : null;
      if (!rb) return;
