        const _SLB2_ROLE_LABELS = { damage: 'DAMAGE', damageEffect: 'DMG+FX', effect: 'EFFECT', heal: 'HEAL', utility: 'UTILITY',
            movement: 'MOVE', deploy: 'DEPLOY', terrain: 'TERRAIN', passive: 'PASSIVE' };
