            const kinds = Object.keys(counts.kinds).sort().map(k => ({ k }));
            const owners = Object.keys(counts.owners).sort((a, b) => a.localeCompare(b)).map(k => ({ k }));
            const lintRules = Object.keys(counts.lint).sort().map(k => ({ k }));
