                return `<div class="slb2-th slb-pri-${c.pri}${s >= 0 ? ' on' : ''}" data-act="sort" data-key="${c.key}" title="sort by ${c.label || 'edit state'} · shift-click = second key">${c.label}${s >= 0 ? `<i>${dir}${_slbSort.length > 1 ? s + 1 : ''}</i>` : ''}</div>`;
