                <div class="slb2-card-top"><span class="slb2-tier t${r.tier}">${_slb2TierText(r.tier)}</span><span class="slb2-card-name" title="${_slbEsc(r.id)}">${_slbEsc(d.name || r.id)}</span>${_slb2Cell('edit', r)}</div>
